CREATE OR REPLACE FUNCTION public.read_channel_credential(p_name text) RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path TO '' AS $$ SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name=p_name AND p_name IN ('CEYO_TELEGRAM_CHANNEL_TOKEN','CEYO_XCHAT_TOKEN','CEYO_XCHAT_PIN','CEYO_XCHAT_USER_ID','CEYO_XCHAT_KEY_VERSION','CEYO_XCHAT_FINGERPRINT','CEYO_XCHAT_CONSUMER_SECRET','CEYO_XCHAT_CONSUMER_KEY','CEYO_XCHAT_CLIENT_ID','CEYO_XCHAT_CLIENT_SECRET') LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.store_channel_credential(p_name text,p_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$ DECLARE sid uuid; BEGIN IF p_name NOT IN ('CEYO_TELEGRAM_CHANNEL_TOKEN','CEYO_XCHAT_TOKEN','CEYO_XCHAT_PIN','CEYO_XCHAT_USER_ID','CEYO_XCHAT_KEY_VERSION','CEYO_XCHAT_FINGERPRINT','CEYO_XCHAT_CONSUMER_SECRET','CEYO_XCHAT_CONSUMER_KEY','CEYO_XCHAT_CLIENT_ID','CEYO_XCHAT_CLIENT_SECRET') OR p_value IS NULL OR length(p_value)=0 THEN RAISE EXCEPTION 'Invalid credential'; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_name)); SELECT id INTO sid FROM vault.secrets WHERE name=p_name LIMIT 1; IF sid IS NULL THEN PERFORM vault.create_secret(p_value,p_name,'Official messaging channel'); ELSE PERFORM vault.update_secret(sid,p_value,p_name,'Official messaging channel'); END IF; END $$;
REVOKE ALL ON FUNCTION public.read_channel_credential(text),public.store_channel_credential(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.read_channel_credential(text),public.store_channel_credential(text,text) TO service_role;